// Demo backend: same interface as db-supabase.js, but local data.
// Starts from dev/demo-data.json (generated by scripts/import_sheet.py) and saves
// changes to this browser's localStorage. Only for trying out the app.

const CHIAVE = 'piante-demo-v1';
const TIPI = [
  { codice: 'acqua', nome: 'Annaffiatura', emoji: '💧', ordine: 1 },
  { codice: 'concime', nome: 'Concimazione', emoji: '🌱', ordine: 2 },
  { codice: 'rinvaso', nome: 'Rinvaso', emoji: '🪴', ordine: 3 },
];
const UTENTE = { id: 'demo', email: 'demo@locale' };

function leggi() {
  try {
    return JSON.parse(localStorage.getItem(CHIAVE));
  } catch {
    return null;
  }
}

export function createDemoDb() {
  let dati = null;

  const salva = () => {
    try {
      localStorage.setItem(CHIAVE, JSON.stringify(dati));
    } catch {
      /* no storage: changes are lost on reload */
    }
  };

  async function carica() {
    if (dati) return dati;
    dati = leggi();
    if (!dati) {
      try {
        const r = await fetch('dev/demo-data.json');
        dati = r.ok ? await r.json() : { piante: [], eventi: [] };
      } catch {
        dati = { piante: [], eventi: [] };
      }
      salva();
    }
    return dati;
  }

  return {
    async getUser() {
      return UTENTE;
    },
    async accedi() {
      return UTENTE;
    },
    async esci() {
      try {
        localStorage.removeItem(CHIAVE);
      } catch {}
      dati = null;
    },
    async caricaTutto() {
      const d = await carica();
      return { piante: structuredClone(d.piante), tipi: TIPI, eventi: structuredClone(d.eventi) };
    },
    async aggiungiPianta({ nome, icona }) {
      const d = await carica();
      const p = { id: crypto.randomUUID(), nome, icona, archiviata: false };
      d.piante.push(p);
      salva();
      return { ...p };
    },
    async aggiornaPianta(id, modifiche) {
      const d = await carica();
      Object.assign(d.piante.find((p) => p.id === id), modifiche);
      salva();
    },
    async registraEvento(piantaId, data, azioni, nota = null) {
      const d = await carica();
      const id = crypto.randomUUID();
      d.eventi.push({ id, pianta_id: piantaId, data, nota, autore: UTENTE.email, creato_il: new Date().toISOString(), azioni });
      salva();
      return id;
    },
    async eliminaEvento(id) {
      const d = await carica();
      d.eventi = d.eventi.filter((e) => e.id !== id);
      salva();
    },
  };
}
